
*{box-sizing:border-box}html,body{margin:0;background:#090a0c;color:#fff;font-family:Arial,Helvetica,sans-serif}
body{min-height:100vh}.app{max-width:1100px;margin:auto;min-height:100vh;background:#0b0c0f}
.header{position:sticky;top:0;z-index:20;background:#08090b;border-bottom:1px solid #27292d}
.header-inner{height:88px;display:flex;align-items:center;padding:0 28px;gap:30px}
.logo{font-weight:900;font-style:italic;letter-spacing:-2px;font-size:34px;color:#ed1c24;line-height:.8}
.logo span{display:block;color:#fff;font-size:12px;letter-spacing:7px;text-align:center;margin-top:8px;font-style:normal}
.nav{margin-left:auto;display:flex;height:100%}.nav button{background:none;border:0;color:#ddd;padding:0 20px;font-weight:800;font-size:16px;cursor:pointer;border-left:1px solid #202226}
.nav button.active{color:#ed1c24;box-shadow:inset 0 -3px #ed1c24}
main{padding-bottom:70px}.screen{display:none}.screen.active{display:block}
.hero{position:relative;min-height:465px;padding:55px 45% 40px 48px;background-size:cover;background-position:center right;background-repeat:no-repeat;background-image:linear-gradient(90deg,rgba(5,6,8,.72) 0%,rgba(5,6,8,.38) 32%,rgba(5,6,8,.06) 60%,rgba(5,6,8,0) 82%),url("data:image/png;base64,");background-size:cover;background-position:center}
.kicker{color:#ed1c24;font-size:12px;font-weight:900;letter-spacing:2px}.hero h1{font-size:42px;line-height:1.02;margin:12px 0}.hero h1 span{color:#ed1c24}.hero p{color:#c7c9cd;line-height:1.6;font-size:16px}
.btn{border:0;background:#e51b23;color:#fff;border-radius:12px;padding:15px 22px;font-weight:900;cursor:pointer}.btn.dark{background:#191b1f;border:1px solid #34373d}
.section{padding:28px 30px}.section h2{margin:0 0 16px;font-size:22px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.card{background:#121418;border:1px solid #282b30;border-radius:14px;padding:18px;cursor:pointer}.card:hover{border-color:#e51b23}.card b{display:block;margin-top:9px}.card small{color:#8f949c}
.feature{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.feature .card{display:flex;gap:12px;align-items:center}.icon{width:42px;height:42px;border-radius:11px;background:#e51b23;display:grid;place-items:center;font-size:20px}
.form-wrap{max-width:650px;margin:auto;padding:35px 20px}.panel{background:#121418;border:1px solid #292c31;border-radius:18px;padding:25px}.panel h2{margin-top:0}.field{margin:14px 0}.field label{display:block;font-size:12px;font-weight:800;color:#aeb2b8;margin-bottom:7px;text-transform:uppercase}.field input{width:100%;padding:14px;border-radius:10px;border:1px solid #34373d;background:#0c0e11;color:#fff;font-size:16px}
.plate-box{max-width:650px;margin:35px auto;padding:0 20px}.plate-row{display:flex;gap:9px}.plate-row input{flex:1;padding:16px;border-radius:12px;border:1px solid #383b41;background:#121418;color:#fff;font-size:20px;text-transform:uppercase}.vehicle{display:none;margin-top:18px}.vehicle.show{display:block}.vehicle .ok{color:#39c979;font-weight:800}.chips{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.chip{background:#22252a;padding:8px 11px;border-radius:999px;color:#d4d7dc;font-size:12px}.search{margin-top:18px}.search input{width:100%;padding:15px;border-radius:11px;border:1px solid #34373d;background:#0e1013;color:#fff;font-size:15px}
.products{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.product{background:#121418;border:1px solid #292c31;border-radius:15px;padding:18px}.product .price{font-size:19px;font-weight:900;margin-top:12px}.stock{color:#39c979;font-size:12px;font-weight:800;margin-top:5px}
.footer-note{text-align:center;color:#6f747c;font-size:11px;padding:20px}
@media(max-width:760px){.header-inner{height:74px;padding:0 15px}.logo{font-size:26px}.logo span{font-size:9px}.nav button{padding:0 9px;font-size:11px}.hero{min-height:520px;padding:35px 22px;background-size:cover;background-position:center;background-repeat:no-repeat;background-image:linear-gradient(0deg,rgba(5,6,8,.90) 8%,rgba(5,6,8,.50) 48%,rgba(5,6,8,.05) 78%),url("data:image/png;base64,");background-position:center top}.hero h1{font-size:34px;margin-top:10px}.section{padding:24px 16px}.grid{grid-template-columns:repeat(2,1fr)}.feature{grid-template-columns:1fr}.products{grid-template-columns:1fr}.plate-box{padding:0 16px}.plate-row{flex-direction:column}}

.part-photo{height:150px;border-radius:14px;background:#f1f2f3;display:flex;align-items:center;justify-content:center;font-size:64px;margin-bottom:14px;border:1px solid #ddd}
.part-photo::after{content:""}


/* ===== STYLE BLOCK ===== */

/* Keep only the primary header navigation */
body > .app > nav,
.app > nav:not(.nav),
.legacy-nav,.bottom-nav,.duplicate-nav{display:none!important}
.fp-login{display:none;margin-top:18px;padding-top:18px;border-top:1px solid #292c31}.fp-login.show{display:block}
.fp-link{background:none;border:0;color:#ed1c24;font-weight:800;cursor:pointer;padding:8px 0;font-size:13px}.fp-back{background:none;border:0;color:#aaa;font-weight:700;cursor:pointer;margin-bottom:10px}
.fp-message{font-size:12px;color:#39c979;margin-top:9px;display:none}.fp-error{font-size:12px;color:#ff6268;margin-top:9px;display:none}
.form-help{font-size:12px;color:#8f959e;line-height:1.5;margin:8px 0 14px}


/* ===== STYLE BLOCK ===== */

/* A navegação oficial é somente a que fica dentro de .header .nav */
body > .app > nav:not(.header .nav),
body > .app > .bottom-nav,
body > .app > .duplicate-nav,
body > .app > .legacy-nav { display:none !important; }


/* ===== STYLE BLOCK ===== */

/* The V3 main header is the only navigation bar. */
header.header nav.nav { display:flex !important; }
/* Never show any secondary/duplicate navigation below the main header. */
main nav, main .nav, main .bottom-nav, main .legacy-nav, main .duplicate-nav { display:none !important; }


/* ===== STYLE BLOCK ===== */

.nav button{font-size:17px;padding:0 16px}.nav{flex-wrap:nowrap}
#welcome .products{grid-template-columns:repeat(3,1fr)}
@media(max-width:760px){.nav button{font-size:15px;padding:0 9px}.header-inner{overflow-x:auto}.nav{min-width:max-content}.hero{padding:45px 24px 35px}.hero h1{font-size:30px}#welcome .products{grid-template-columns:1fr}}


/* ===== STYLE BLOCK ===== */

.field.password-field{position:relative}.password-toggle{position:absolute;right:12px;bottom:10px;width:24px;height:24px;border:0;background:transparent;color:#8b9199;cursor:pointer;padding:0;line-height:24px;opacity:.8}.password-toggle svg{width:17px;height:17px;display:block;margin:3px auto;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.password-toggle:hover{color:#fff;opacity:1}.password-toggle:hover{color:#fff}.cart-icon{font-size:20px;line-height:1;display:inline-block}.nav button[data-screen="carrinho"]{min-width:44px;padding-left:10px;padding-right:10px}


/* ===== STYLE BLOCK ===== */
.fp-whatsapp-float{position:fixed;right:20px;bottom:20px;width:52px;height:52px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#25D366;color:#fff;text-decoration:none;box-shadow:0 8px 24px rgba(0,0,0,.28);z-index:9999}.fp-whatsapp-float svg{width:27px;height:27px;fill:currentColor}.fp-wa-btn{display:inline-flex;align-items:center;gap:8px;text-decoration:none}.fp-wa-btn svg{width:18px;height:18px;fill:currentColor}

/* ===== STYLE BLOCK ===== */

/* Navegação por estado: visitante x cliente logado */
body:not(.logged-in) .nav button[data-screen="perfil"]{display:none !important;}
body.logged-in .nav button[data-screen="cadastro"]{display:none !important;}



/* ===== STYLE BLOCK ===== */

.visitor-quick-actions{display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin:18px auto;max-width:720px}
.visitor-quick-actions .btn{min-width:180px}
.plate-promo{margin:20px auto 28px;max-width:900px;padding:28px;border:1px solid rgba(255,255,255,.10);border-radius:18px;background:linear-gradient(135deg,rgba(255,255,255,.05),rgba(255,255,255,.02));text-align:center}
.plate-promo h2{margin:8px 0;font-size:clamp(22px,4vw,34px)}
.plate-promo p{color:#aeb3ba;margin:0}

/* Atalhos de cadastro/login e propaganda por placa aparecem somente no Início da Tela 1. */
#visitorQuickActions, .plate-promo { display:none; }
body.visitor-inicio #visitorQuickActions, body.visitor-inicio .plate-promo { display:flex; }


/* ===== STYLE BLOCK — modernização visual (mesmas cores, logo e estrutura originais) ===== */

:root{
  --red:#ed1c24;
  --red-2:#e51b23;
  --red-glow:rgba(237,28,36,.35);
  --border:#282b30;
  --radius-lg:18px;
  --ease:cubic-bezier(.2,.7,.2,1);
}

*{font-family:'Inter',Arial,Helvetica,sans-serif}

html,body{scrollbar-color:#3a3d43 #0b0c0f}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:#0b0c0f}
::-webkit-scrollbar-thumb{background:#2a2d33;border-radius:8px}
::-webkit-scrollbar-thumb:hover{background:#3a3d43}

/* Cabeçalho com leve efeito de vidro ao rolar a página */
.header{backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);background:rgba(8,9,11,.86)}

.nav button{transition:color .2s var(--ease),box-shadow .2s var(--ease)}
.nav button:hover{color:#fff}

/* Botões com profundidade e transição suave ao interagir */
.btn{transition:transform .18s var(--ease),box-shadow .18s var(--ease),filter .18s var(--ease);box-shadow:0 6px 18px -6px var(--red-glow)}
.btn:hover{transform:translateY(-1px);filter:brightness(1.08);box-shadow:0 10px 26px -6px var(--red-glow)}
.btn:active{transform:translateY(0);filter:brightness(.97)}
.btn.dark{box-shadow:none}
.btn.dark:hover{background:#22252a}
.btn.secondary{box-shadow:none}

/* Cards, produtos e painéis com leve elevação ao passar o mouse */
.card,.product,.panel{transition:transform .2s var(--ease),box-shadow .2s var(--ease),border-color .2s var(--ease)}
.card:hover,.product:hover{transform:translateY(-3px);box-shadow:0 14px 30px -12px rgba(0,0,0,.55)}
.panel{box-shadow:0 20px 45px -20px rgba(0,0,0,.5)}

/* Foto de peça combinando com o tema escuro em vez do branco puro */
.part-photo{background:linear-gradient(155deg,#1b1d22,#101215);border-color:var(--border);color:#e7e8ea}

/* Selo de estoque em formato de pílula, mais legível */
.stock{display:inline-flex;align-items:center;gap:5px;background:rgba(57,201,121,.12);padding:4px 10px;border-radius:999px}

/* Campos de formulário com foco visível e suave */
.field input,.plate-row input,.search input,#filterCategory,#filterMinPrice,#filterMaxPrice{transition:border-color .18s var(--ease),box-shadow .18s var(--ease)}
.field input:focus,.plate-row input:focus,.search input:focus,#filterCategory:focus,#filterMinPrice:focus,#filterMaxPrice:focus{outline:none;border-color:var(--red);box-shadow:0 0 0 3px var(--red-glow)}

/* Transição suave ao trocar de tela */
.screen.active{animation:fp-fade .35s var(--ease)}
@keyframes fp-fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}

/* Botão do WhatsApp com leve resposta ao passar o mouse */
.fp-whatsapp-float{transition:transform .2s var(--ease)}
.fp-whatsapp-float:hover{transform:scale(1.08)}


/* ===== STYLE BLOCK — otimização para celular (interface do cliente) ===== */

@media(max-width:600px){
  .header-inner{height:64px;padding:0 16px;gap:14px}
  .logo{font-size:24px;letter-spacing:-1px}
  .logo span{font-size:9px;letter-spacing:4px;margin-top:5px}
  .nav button{padding:0 10px;font-size:13px}
  .cart-icon{font-size:17px}

  .visitor-quick-actions{flex-direction:column;margin:14px auto;padding:0 16px}
  .visitor-quick-actions .btn{width:100%;min-width:0}

  .hero{padding:32px 18px 28px}
  .hero h1{font-size:clamp(24px,7vw,32px)}
  .hero p{font-size:14px}
  .hero > div[style*="display:flex"]{flex-direction:column}
  .hero > div[style*="display:flex"] .btn{width:100%;text-align:center}
  .hero .btn{width:100%;text-align:center;justify-content:center}

  .section{padding:20px 16px}
  .section h2{font-size:19px}

  .grid{grid-template-columns:repeat(2,1fr);gap:10px}
  .feature{grid-template-columns:1fr;gap:10px}
  .products{grid-template-columns:1fr;gap:10px}

  .plate-box{margin:22px auto;padding:0 16px}
  .plate-row{flex-direction:column}
  .plate-row input,.plate-row .btn{width:100%}

  .catalog-filters{gap:8px}
  .catalog-filters .field{min-width:calc(50% - 4px)!important;flex:none!important}

  .form-wrap{padding:22px 16px}
  .panel{padding:18px}

  .product .btn,.card.add-cart{width:100%}
  .products .btn{width:100%}

  .cart-row{flex-wrap:wrap;gap:8px!important}
  .cart-row > div:first-child{flex:1 1 100%;order:1}
  .cart-row .qty-minus,.cart-row .qty-plus{width:34px;height:34px;order:2}
  .cart-row .remove-item{order:4;margin-left:auto}

  .fp-whatsapp-float{width:46px;height:46px;right:14px;bottom:14px}
  .fp-whatsapp-float svg{width:23px;height:23px}
}

@media(max-width:380px){
  .grid{grid-template-columns:1fr}
  .logo{font-size:21px}
  .nav button{padding:0 8px;font-size:12px}
}


/* ===== STYLE BLOCK — imagem do hero em destaque + ícones modernizados ===== */

/* Texto do hero com leve sombra para continuar legível com a imagem mais visível */
.hero .kicker{text-shadow:0 2px 10px rgba(0,0,0,.6)}
.hero h1{text-shadow:0 4px 18px rgba(0,0,0,.65)}
.hero p{text-shadow:0 2px 12px rgba(0,0,0,.6)}

/* Ícones das 3 features em badge circular, mais moderno que o quadrado sólido */
.icon{
  width:48px;height:48px;border-radius:50%;
  background:rgba(237,28,36,.12);
  border:1px solid rgba(237,28,36,.4);
  color:var(--red);
  box-shadow:0 0 0 4px rgba(237,28,36,.06);
}
.feature .card{transition:border-color .2s var(--ease)}
.feature .card:hover{border-color:rgba(237,28,36,.5)}
.feature .card:hover .icon{background:rgba(237,28,36,.2);transform:scale(1.05)}
.icon svg{transition:transform .2s var(--ease)}


/* ===== STYLE BLOCK — selo "FAHREN PARTS" reposicionado + imagem de fundo preenchendo o banner ===== */

.hero-badge{
  position:absolute;
  top:22px;left:48px;
  display:inline-block;
  background:rgba(9,10,12,.55);
  border:1px solid rgba(255,255,255,.14);
  color:var(--red);
  font-size:11px;font-weight:900;letter-spacing:2px;
  padding:6px 14px;border-radius:999px;
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
}
.hero h1{margin-top:52px}

@media(max-width:600px){
  .hero-badge{top:16px;left:18px;font-size:10px;padding:5px 11px}
  .hero h1{margin-top:38px}
}


/* ===== STYLE BLOCK — carrossel automático de categorias ===== */

.carousel{
  position:relative;
  overflow:hidden;
  margin:0 -30px;
  padding:2px 0;
  -webkit-mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent);
  mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent);
}
.carousel-track{
  display:flex;
  width:max-content;
  gap:12px;
  padding:0 30px;
  animation:fp-carousel 32s linear infinite;
}
.carousel:hover .carousel-track{animation-play-state:paused}
.carousel .card{
  flex:0 0 180px;
  text-align:center;
  font-size:34px;
}
.carousel .card b{font-size:14px}
.carousel .card small{font-size:11px}

@keyframes fp-carousel{
  from{transform:translateX(0)}
  to{transform:translateX(-50%)}
}

@media(max-width:600px){
  .carousel{margin:0 -16px}
  .carousel-track{padding:0 16px;gap:10px}
  .carousel .card{flex:0 0 150px;font-size:28px}
}

@media(prefers-reduced-motion:reduce){
  .carousel-track{animation:none}
  .carousel{overflow-x:auto}
}


/* ===== STYLE BLOCK — categorias com fotos reais das peças ===== */

.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}
.section-head h2{margin:0}
.ver-todas{background:none;border:0;color:var(--red);font-weight:900;font-size:12px;letter-spacing:1px;cursor:pointer;display:inline-flex;align-items:center;gap:4px;padding:6px 0;transition:gap .18s var(--ease)}
.ver-todas:hover{gap:8px}
.ver-todas span{font-size:15px;line-height:1}

.cat-card{padding:0;overflow:hidden;text-align:left;font-size:0}
.cat-card img{width:100%;height:112px;object-fit:cover;display:block;background:#0c0e11}
.cat-card b,.cat-card small{display:block;padding:0 14px;font-size:14px}
.cat-card b{margin-top:12px}
.cat-card small{margin:2px 0 14px;color:#8f949c;font-size:12px}

.carousel .cat-card{flex:0 0 190px}
@media(max-width:600px){
  .carousel .cat-card{flex:0 0 160px}
  .cat-card img{height:96px}
}


/* ===== STYLE BLOCK — filtro de categoria modernizado, sem preço/estoque min-max ===== */

.catalog-filters{margin-top:14px;max-width:340px}
.select-modern{
  position:relative;
  display:flex;align-items:center;gap:10px;
  background:#0e1013;
  border:1px solid #34373d;
  border-radius:12px;
  padding:0 14px;
  transition:border-color .18s var(--ease),box-shadow .18s var(--ease);
}
.select-modern:focus-within{border-color:var(--red);box-shadow:0 0 0 3px var(--red-glow)}
.select-modern-icon{flex:0 0 auto;color:var(--red)}
.select-modern select{
  appearance:none;-webkit-appearance:none;
  flex:1;
  background:transparent;
  border:0;
  color:#fff;
  font-size:15px;
  font-weight:600;
  padding:14px 0;
  cursor:pointer;
}
.select-modern select:focus{outline:none}
.select-modern-chevron{flex:0 0 auto;color:#8b9199;pointer-events:none}

.stock-qty{color:#8f949c;font-weight:400}


/* ===== STYLE BLOCK ===== */

/* Botão "Voltar" — some no cabeçalho e leva para a tela anterior dentro do
   site (histórico do próprio app), evitando sair do site ao usar o botão
   Voltar do navegador. Só aparece quando existe algo para onde voltar. */
.back-btn{display:none;align-items:center;justify-content:center;flex:0 0 auto;width:38px;height:38px;border-radius:50%;border:1px solid #292c31;background:#121418;color:#fff;margin-right:14px;cursor:pointer;transition:background .15s,border-color .15s,color .15s,transform .1s}
.back-btn svg{width:19px;height:19px;display:block}
.back-btn:hover{border-color:#ed1c24;color:#ed1c24}
.back-btn:active{transform:scale(.9)}
.back-btn.show{display:inline-flex}
@media(max-width:600px){
  .back-btn{width:33px;height:33px;margin-right:8px}
  .back-btn svg{width:16px;height:16px}
}


/* ===== STYLE BLOCK ===== */

/* Peças do catálogo agora usam foto real (da própria categoria, quando a
   peça não tem foto cadastrada) preenchendo o quadro, em vez do ícone/emoji
   genérico centralizado. */
.part-photo{padding:0;overflow:hidden}
.part-photo img{width:100%;height:100%;object-fit:cover;display:block;border-radius:inherit}


/* ===== STYLE BLOCK — forma de pagamento (Pix, cartão, retirada/entrega) ===== */

.payment-option{display:flex;align-items:center;gap:12px;padding:14px 16px;border:1px solid var(--border);border-radius:12px;margin-bottom:10px;cursor:pointer;transition:border-color .15s,background .15s}
.payment-option:hover{border-color:#3a3d43}
.payment-option.selected{border-color:var(--red);background:rgba(237,28,36,.07)}
.payment-option input[type="radio"]{width:18px;height:18px;accent-color:var(--red);flex:0 0 auto;cursor:pointer}
.payment-option-body{flex:1;min-width:0}
.payment-option-body b{display:block;font-size:14px;line-height:1.3}
.payment-option-body small{color:#9da2aa;font-size:12px;line-height:1.4}
.payment-option-price{font-weight:900;white-space:nowrap;font-size:14px}
.payment-panel{margin-top:14px}
.payment-panel .kicker{margin-bottom:4px}
#pixCode{font-family:ui-monospace,Consolas,monospace;word-break:break-all}
@media(max-width:480px){
  .payment-option{padding:12px}
  .payment-option-price{font-size:13px}
}


/* ===== STYLE BLOCK — QR Code do Pix ===== */

.pix-qr-box{display:flex;justify-content:center;margin-top:4px}
.pix-qr-box svg{width:180px;height:180px;max-width:100%;border-radius:8px;display:block}
@media(max-width:480px){
  .pix-qr-box svg{width:150px;height:150px}
}

/* ===== Logo interativo e Badge do Carrinho ===== */
.logo {
  cursor: pointer !important;
  user-select: none !important;
  transition: opacity 0.15s ease, transform 0.15s ease;
}
.logo:hover {
  opacity: 0.9;
  transform: scale(1.02);
}
.logo:active {
  transform: scale(0.98);
}

.nav-cart-btn {
  position: relative !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 7px !important;
  padding: 0 16px !important;
  cursor: pointer !important;
}
.nav-cart-label {
  font-size: 15px;
  font-weight: 800;
  display: inline-block;
}
.cart-badge {
  background: #24272d;
  color: #aeb3ba;
  font-size: 11px;
  font-weight: 900;
  min-width: 20px;
  height: 20px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border: 1.5px solid #373a40;
  line-height: 1;
  pointer-events: none;
  transition: all .2s ease;
}
.cart-badge.has-items {
  background: #e51b23 !important;
  color: #ffffff !important;
  border-color: #090a0c !important;
  box-shadow: 0 2px 10px rgba(229, 27, 35, 0.75) !important;
  animation: badgePop 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
@keyframes badgePop {
  0% { transform: scale(0.5); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

/* ===== Seletor de Quantidade nos Cards de Peças ===== */
.product-qty-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.qty-label {
  font-size: 11px;
  color: #9da2aa;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.qty-control {
  display: flex;
  align-items: center;
  gap: 2px;
  background: #090a0c;
  padding: 2px 3px;
  border-radius: 8px;
  border: 1px solid #282b30;
}
.btn-qty-btn {
  width: 28px;
  height: 28px;
  background: #1c1e22;
  color: #fff;
  border: 1px solid #34373d;
  border-radius: 6px;
  cursor: pointer;
  font-size: 16px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background .15s, border-color .15s, transform .1s;
}
.btn-qty-btn:hover {
  background: #2b2e35;
  border-color: #ed1c24;
}
.btn-qty-btn:active {
  transform: scale(0.92);
}
.product-qty-val {
  width: 36px;
  height: 28px;
  text-align: center;
  background: transparent;
  color: #fff;
  border: none;
  font-size: 14px;
  font-weight: 800;
  outline: none;
  -moz-appearance: textfield;
}
.product-qty-val::-webkit-outer-spin-button,
.product-qty-val::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.add-cart-btn {
  margin-top: 10px !important;
  width: 100% !important;
  transition: all .2s ease !important;
}
.add-cart-btn.added-feedback {
  background: #238636 !important;
  border-color: #2ea043 !important;
  color: #ffffff !important;
  box-shadow: 0 0 14px rgba(46, 160, 67, 0.4) !important;
  transform: scale(1.02);
}

/* ===== Toast Notification (Feedback instantâneo sem sair da tela) ===== */
#toastContainer {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 99999;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}
.fp-toast {
  pointer-events: auto;
  background: #14171d;
  color: #ffffff;
  padding: 12px 18px;
  border-radius: 12px;
  border: 1px solid #34373d;
  box-shadow: 0 10px 32px rgba(0, 0, 0, 0.75), 0 0 12px rgba(237, 28, 36, 0.25);
  display: flex;
  align-items: center;
  gap: 12px;
  animation: toastSlideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  max-width: calc(100vw - 48px);
}
@keyframes toastSlideUp {
  from { transform: translateY(40px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}
.fp-toast-msg {
  font-size: 13.5px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 6px;
  color: #f0f2f5;
}
.fp-toast-btn {
  background: #ed1c24;
  color: #fff;
  border: none;
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  transition: background .15s, transform .1s;
}
.fp-toast-btn:hover {
  background: #ff2a32;
  transform: scale(1.03);
}
.fp-toast-close {
  background: transparent;
  border: none;
  color: #8b9199;
  font-size: 16px;
  cursor: pointer;
  padding: 0 4px;
  line-height: 1;
}
.fp-toast-close:hover {
  color: #fff;
}

